def rerank_rows(rows, scores):
    if len({row['id'] for row in rows}) != len(rows):
        raise ValueError('duplicate candidate')
    checked = checked_scores(scores, len(rows))
    result = [dict(row, score=score) for row, score in zip(rows, checked, strict=True)]
    return sorted(result, key=lambda row: (-row['score'], row['retrieval_rank'], row['id']))

