def make_query_plan(original, rewrites=()):
    required = protected_terms(original)
    if not isinstance(rewrites, (list, tuple)) or len(rewrites) > 2:
        raise ValueError('at most two raw rewrites')
    planned = [original]
    for rewrite in rewrites:
        terms = protected_terms(rewrite)
        if not required <= terms:
            raise ValueError('protected term lost')
        if rewrite not in planned:
            planned.append(rewrite)
    return tuple(planned)

def validate_budgets(evidence, candidates, depth, chars, sentences=2, compression='none'):
    if any(type(x) is not int for x in (evidence,candidates,depth,chars,sentences)):
        raise ValueError('exact integer required')
    if not (1 <= evidence <= candidates <= depth <= 32 and 2 <= chars <= 16000 and 1 <= sentences <= 4):
        raise ValueError('invalid count or budget')
    if type(compression) is not str or compression not in {'none','sentences'}:
        raise ValueError('unsupported compression')
    return dict(evidence_count=evidence,candidate_count=candidates,retrieval_depth=depth,context_chars=chars,max_sentences=sentences,compression=compression)

def dedupe_evidence(rows):
    seen = set()
    kept, dropped = [], []
    for row in rows:
        key = tuple(row[k] for k in ('tenant_id','document_id','version','digest','text'))
        if key in seen:
            dropped.append(row['id'])
        else:
            seen.add(key)
            kept.append(row)
    return kept, dropped

