def select_spans(query, text, limit=2, table_row=False):
    if not isinstance(query,str) or not query.strip() or len(query)>1000 or not isinstance(text,str) or not text.strip() or len(text)>4000:
        raise ValueError('invalid pair')
    if type(limit) is not int or not 1<=limit<=4 or type(table_row) is not bool:
        raise ValueError('invalid selection policy')
    if table_row:
        return ((0,len(text)),)
    def terms(value):
        return set(re.findall(r'[a-z0-9]+(?:[-_/][a-z0-9]+)*',value.lower()))
    wanted = terms(query)
    spans = sorted(sentence_spans(text),key=lambda s:(-len(wanted & terms(text[s[0]:s[1]])),s[0]))[:limit]
    return tuple(sorted(spans))

