def pack_units(units, chars, evidence_count):
    if type(chars) is not int or not 2<=chars<=16000 or type(evidence_count) is not int or not 1<=evidence_count<=32:
        raise ValueError('invalid admission budget')
    selected = []
    admitted = 0
    for unit in units:
        if admitted >= evidence_count:
            break
        proposed = [*selected]
        for span in unit:
            proposed.append(dict(span,citation_id=f'S{len(proposed)+1}'))
        if len(render_context(proposed)) <= chars:
            selected = proposed
            admitted += 1
    return selected

def support_complete(spans, required):
    if not required:
        return None
    return all(any(s['evidence_key']==key and atom.casefold() in s['quote'].casefold() for s in spans) for key,atoms in required.items() for atom in atoms)

def result_status(candidate_count, span_count):
    if type(candidate_count) is not int or type(span_count) is not int or not (0<=candidate_count<=32 and 0<=span_count<=128 and span_count<=4*candidate_count):
        raise ValueError('invalid availability counts')
    if span_count:
        return 'evidence_available'
    return 'no_evidence' if candidate_count==0 else 'context_budget_exhausted'

def unique_records(records):
    fields = {'tenant_id','document_id','version','supplier','text'}
    if not isinstance(records,(list,tuple)) or not 1<=len(records)<=32:
        raise ValueError('invalid record batch')
    seen = {}
    result = []
    for row in records:
        if not isinstance(row,dict) or set(row)!=fields:
            raise ValueError('unexpected fields')
        for key,value in row.items():
            if not isinstance(value,str) or not value.strip() or len(value)>(1000 if key=='text' else 200):
                raise ValueError('invalid field')
            value.encode('utf-8')
        identity = tuple(row[k] for k in ('tenant_id','document_id','version'))
        if identity in seen:
            if seen[identity] != row:
                raise ValueError('conflicting source version')
        else:
            copy = dict(row)
            seen[identity] = copy
            result.append(copy)
    return result

