import math
def decode_unique_json(text):
    if not isinstance(text,str) or not text.strip() or len(text.encode('utf-8'))>131072:
        raise ValueError('bounded UTF-8 JSON required')
    def object_hook(pairs):
        out = {}
        for key,value in pairs:
            if key in out:
                raise ValueError('duplicate JSON key')
            out[key] = value
        return out
    def constant(value):
        raise ValueError('nonfinite JSON number')
    def finite_float(value):
        out = float(value)
        if not math.isfinite(out):
            raise ValueError('nonfinite JSON float')
        return out
    result = json.loads(text,object_pairs_hook=object_hook,parse_constant=constant,parse_float=finite_float)
    if not isinstance(result,dict):
        raise ValueError('object root required')
    return result

def joint_pair_ids(rows, limit, expected_count):
    if type(limit) is not int or not 1<=limit<=8192 or type(expected_count) is not int or not 0<=expected_count<=32:
        raise ValueError('invalid joint contract')
    if not isinstance(rows,list) or len(rows)!=expected_count:
        raise ValueError('wrong pair count')
    if any(not isinstance(r,list) or not 1<=len(r)<=limit or any(type(x) is not int or x<0 for x in r) for r in rows):
        raise ValueError('invalid or overlength joint pair')
    return tuple(tuple(r) for r in rows)

import re
def safe_event(fields):
    keys = ('request_id','candidate_count','selected_span_count','status','manifest_fingerprint')
    if not isinstance(fields,dict) or not set(keys)<=set(fields):
        raise ValueError('required event metadata missing')
    request_id = fields['request_id']
    if not isinstance(request_id,str) or re.fullmatch(r'[A-Za-z0-9_-]{1,64}',request_id) is None:
        raise ValueError('invalid request ID')
    return {key:fields[key] for key in keys}

