import json
def request_digest(manifest):
    keys = {'corpus','partition','query_digests','retrieval_manifests','reranker','config','dedup','context','answer'}
    if not isinstance(manifest,dict) or set(manifest)!=keys:
        raise ValueError('incomplete request identity')
    value = dict(manifest,schema='procurement-assistant/1.0.0')
    payload = json.dumps(value,sort_keys=True,ensure_ascii=False,separators=(',',':'),allow_nan=False).encode('utf-8')
    return hashlib.sha256(payload).hexdigest()

def paired_metrics(pool, reranked, gold, k):
    if type(k) is not int or not 1<=k<=32:
        raise ValueError('invalid cutoff')
    for values in (pool,reranked):
        if not isinstance(values,(list,tuple)) or len(values)>32 or any(not isinstance(v,str) or not v.strip() for v in values) or len(set(values))!=len(values):
            raise ValueError('unique bounded ID list required')
    if not isinstance(gold,(set,frozenset)) or any(not isinstance(v,str) or not v.strip() for v in gold) or len(pool)!=len(reranked) or set(pool)!=set(reranked):
        raise ValueError('same-pool labels required')
    in_pool = len(set(pool)&gold)
    before = len(set(pool[:k])&gold)
    after = len(set(reranked[:k])&gold)
    return dict(candidate_recall=in_pool/len(gold) if gold else None,before_recall=before/len(gold) if gold else None,after_recall=after/len(gold) if gold else None,before_precision=before/k,after_precision=after/k)
